import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, readFile, rm, mkdir, writeFile } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
const profile = await mkdtemp(path.join(os.tmpdir(), 'legendgirl-som-chrome-'));
const chrome = spawn('/Applications/Google Chrome.app/Contents/MacOS/Google Chrome', ['--headless=new', '--mute-audio', '--no-first-run', '--no-default-browser-check', '--autoplay-policy=no-user-gesture-required', '--remote-debugging-port=0', '--user-data-dir='+profile, 'about:blank'], {stdio:'ignore'});
let ws;
try {
 let port;
 for(let i=0;i<100;i++) { try { port=(await readFile(path.join(profile,'DevToolsActivePort'),'utf8')).split('\n')[0];break; } catch {} await new Promise(r=>setTimeout(r,100)); }
 assert.ok(port,'Chrome de QA inicializado');
 const tabs=await (await fetch('http://127.0.0.1:'+port+'/json/list')).json();
 ws=new WebSocket(tabs.find(t=>t.type==='page').webSocketDebuggerUrl);
 await new Promise(r=>ws.onopen=r);
 let id=0;const pending=new Map();ws.onmessage=e=>{const d=JSON.parse(e.data);if(d.id){pending.get(d.id)?.(d);pending.delete(d.id);}};
 const call=(method,params={})=>new Promise(resolve=>{const n=++id;pending.set(n,resolve);ws.send(JSON.stringify({id:n,method,params}));});
 const evaluate=async expression=>{const r=await call('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true});if(r.result?.exceptionDetails)throw Error(JSON.stringify(r.result.exceptionDetails));return r.result?.result?.value;};

 const output='docs/diario-ia/qa-resultados/jardim-v2';await mkdir(output,{recursive:true});const reports=[];
 for(const [name,width,height,mobile]of [['desktop',1280,800,false],['android',390,844,true],['paisagem',844,390,true]]){
  await call('Emulation.setDeviceMetricsOverride',{width,height,deviceScaleFactor:1,mobile});await call('Emulation.setTouchEmulationEnabled',{enabled:mobile});
  await call('Page.navigate',{url:'http://127.0.0.1:3000/tests/dark-room-playthrough.html'});let ready=false;for(let i=0;i<300;i++){if(await evaluate('Boolean(window.review)')){ready=true;break;}await new Promise(r=>setTimeout(r,100));}assert.ok(ready,'Host pronto');
  await evaluate(`(()=>{const c=document.querySelector('canvas');c.width=${width};c.height=${height};c.style.width='${width}px';c.style.height='${height}px';})()`);
  const save=await evaluate("localStorage.getItem('legendGirl.campaign.v1')");
  await evaluate(`(async()=>{window.qa=await import('/docs/diario-ia/qa/jardim-v2/cenario.mjs');await qa.start();})()`);
  const result=await evaluate('qa.audit()');for(const shot of result.shots){const bytes=Buffer.from(shot.data.split(',')[1],'base64');await writeFile(output+'/'+name+'-'+shot.label+'.png',bytes);await writeFile('/tmp/legendgirl-jardim-v6-'+name+'-'+shot.label+'.png',bytes);delete shot.data;}
  const traversals='Percursos integrais medidos separadamente por test:garden:percurso';
  await evaluate("(async()=>{await qa.start();review.game.state.toyRoomInstance.instance.garden.state.stage='RUNNING';review.game.state.toyRoomInstance.instance.garden.state.player.x=250;review.game.setPaused(false);})()");
  if(!mobile){await call('Input.dispatchKeyEvent',{type:'keyDown',code:'KeyD',key:'d'});await call('Input.dispatchKeyEvent',{type:'keyDown',code:'Space',key:' '});}else{
   const b=await evaluate('qa.controls()');await call('Input.dispatchTouchEvent',{type:'touchStart',touchPoints:[{x:b.right.x,y:b.right.y,id:1},{x:b.jump.x,y:b.jump.y,id:2}]});
  }
  await new Promise(r=>setTimeout(r,180));const input=await evaluate('(()=>{const p=review.game.state.toyRoomInstance.instance.garden.state.player;const phase=review.game.state.toyRoomInstance.instance.garden;return{x:p.x,y:p.y,keys:[...phase.input.keys],enabled:phase.input.enabled(),paused:phase.paused,hostPaused:review.game.isPaused(),stage:phase.state.stage,visible:document.visibilityState,loop:review.game.state.loopStarted};})()');console.log(name,'ENTRADA',JSON.stringify(input));assert.ok(input.x>260&&input.y<580,'Andar e pular simultaneamente por entrada real');
  if(!mobile){await call('Input.dispatchKeyEvent',{type:'keyUp',code:'KeyD',key:'d'});await call('Input.dispatchKeyEvent',{type:'keyUp',code:'Space',key:' '});}else await call('Input.dispatchTouchEvent',{type:'touchEnd',touchPoints:[]});
  await evaluate('review.game.setPaused(true)');assert.equal(await evaluate("review.game.state.toyRoomInstance.instance.garden.input.pointers.size"),0,'Pausa solta os ponteiros');
  assert.equal(await evaluate("localStorage.getItem('legendGirl.campaign.v1')"),save,'Revisão não sobrescreve campanha');reports.push({name,...result,traversals,input});
 }
 await writeFile(output+'/resultado.json',JSON.stringify(reports,null,2));console.log(JSON.stringify(reports,null,2));console.log('APROVADO: arte real, chão fixo contínuo, três formatos, teclado/toque/gamepad, câmera lateral, transição, save, pausa, resgate/desorientação EASY e descarte. Travessias integrais têm comando separado.');
}finally{ws?.close();chrome.kill();await new Promise(r=>chrome.once('exit',r));await rm(profile,{recursive:true,force:true});}
